#!/usr/bin/env node
/**
 * The pricing parity gate.
 *
 * Two copies of the pricing engine exist on purpose -- Kotlin on the phone,
 * TypeScript on the server -- and never a third. What keeps them one engine
 * is a set of fixtures written by Kotlin under fixtures/pricing/ that BOTH
 * sides must reproduce exactly. This runs both suites and says, in one line
 * each, whether they did.
 *
 * Then the hand-computed money cases (smoke.ts), which are the only check here
 * that can call BOTH engines wrong. The fixtures are generated BY Kotlin, so
 * parity proves agreement and not truth: if a rule is misread, both engines
 * misread it and every fixture agrees. smoke.ts holds figures worked out from
 * the pricing rules by hand -- a $200 labour floor, a grand total to the cent,
 * a gate's post count -- so it is what notices. It ran nowhere at all until
 * 24 Oct 2026 and had been red at 119 of 130 for weeks without a sound.
 *
 * Then two more, for what a commit WRITES, which the fixtures never reach:
 * they prove priceJob's output, not the rows buildCommitPlan turns it into.
 * The rows are where a quantity typed on the phone was lost -- the job sheet
 * re-prices on its own when a rate is saved, and the old plan tombstoned every
 * roled line and upserted the rebuild over it. load_test.ts and
 * tests/price-job-takeoff-merge.test.mjs are the only checks of that rule
 * (never write or tombstone an edited line, write nothing for an unchanged
 * run, and the tombstone UPDATE asking the row itself), so they run here, in
 * the gate deploy-functions.mjs runs before price-job ships.
 *
 * publish-release.mjs and deploy-functions.mjs call this first and refuse to
 * continue when it is red. There is deliberately no --skip flag: the day the
 * gate is skipped is the day the office quotes one number and the phone
 * another, and that is the failure this whole arrangement exists to prevent.
 *
 * Usage:
 *   node scripts/check-parity.mjs
 *
 * Exit status is non-zero when any suite fails, including when the
 * fixtures have not been generated yet -- no evidence is not green.
 *
 * The Kotlin suite needs the two files Gradle reads but git does not carry:
 * local.properties (the SDK path) and app/google-services.json. A fresh
 * worktree has neither; copy them from the main checkout first.
 */
import { spawnSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { join, resolve } from "node:path";

const REPO_ROOT = resolve(import.meta.dirname, "..");
const isWindows = process.platform === "win32";

// JDK 17, explicitly. There is no java on PATH here, and the JDK Android
// Studio bundles is Java 25, which Gradle rejects with a bare "25.0.2" that
// says nothing about what went wrong. The POSIX form is what a Git Bash
// user exports by hand; gradlew.bat needs the Windows spelling of the same
// directory.
//
// FOUND, not hardcoded. This used to name one directory
// (/c/Users/march/.jdks/jdk-17.0.20+8). That disk was replaced, the directory
// went with it, and every publish then died on "JAVA_HOME is set to an
// invalid directory" -- exporting JAVA_HOME by hand did not help, because
// this constant overwrote it a line later. The gate was red for a reason
// that had nothing to do with pricing.
//
// Order: what the caller exported, then the places a JDK 17 actually lives on
// this machine. A directory only counts if it holds a java binary, so a stale
// name can never be chosen over a real one.
const toWindows = (p) =>
  p.replace(/^\/([a-zA-Z])\//, (_, drive) => `${drive.toUpperCase()}:\\`).replace(/\//g, "\\");

const JDK_CANDIDATES = [
  process.env.JAVA_HOME,
  "C:\\Program Files\\Eclipse Adoptium\\jdk-17.0.20.101-hotspot",
  "C:\\Program Files\\Eclipse Adoptium\\jdk-17.0.20+8",
  "C:\\Users\\march\\.jdks\\jdk-17.0.20+8",
].filter(Boolean);

function findJdk() {
  for (const raw of JDK_CANDIDATES) {
    const home = isWindows && raw.startsWith("/") ? toWindows(raw) : raw;
    const java = join(home, "bin", isWindows ? "java.exe" : "java");
    if (existsSync(java)) return home;
  }
  console.error("No JDK 17 found. Looked at:");
  for (const c of JDK_CANDIDATES) console.error("  " + c);
  console.error("");
  console.error("Export JAVA_HOME to a JDK 17 and run again. Gradle rejects the JDK");
  console.error("Android Studio bundles (Java 25) with a bare \"25.0.2\".");
  process.exit(1);
}

const JDK_HOME = findJdk();

/**
 * Runs one suite, prints one line, returns true when it passed. Output is
 * captured rather than streamed so a green run is one line per suite; a red
 * run prints the tail of what the suite said, which is where both gradle
 * and the TypeScript runner put the reason.
 *
 * The command is one string run through the shell: gradlew.bat and npx.cmd
 * are batch files, which Node will not exec without a shell on Windows, and
 * Node warns (DEP0190) when an argument array is combined with shell:true.
 */
function suite(label, commandLine, extraEnv = {}) {
  const started = Date.now();
  const result = spawnSync(commandLine, {
    cwd: REPO_ROOT,
    encoding: "utf8",
    shell: true,
    env: { ...process.env, ...extraEnv },
    maxBuffer: 64 * 1024 * 1024,
  });
  const seconds = ((Date.now() - started) / 1000).toFixed(0);
  const ok = result.status === 0;
  console.log(`${ok ? "ok  " : "FAIL"}  ${label.padEnd(18)} ${seconds}s`);
  if (!ok) {
    const output = `${result.stdout ?? ""}${result.stderr ?? ""}`.trim();
    const lines = output.split(/\r?\n/);
    const tail = lines.slice(Math.max(0, lines.length - 40));
    if (result.error) console.log(`      ${result.error.message}`);
    for (const line of tail) console.log(`      ${line}`);
  }
  return ok;
}

// The wrapper by absolute path, quoted. A bare "gradlew.bat" is not found
// on a machine with NoDefaultCurrentDirectoryInExePath set (this one has
// it): cmd then refuses to look in the current directory for a command,
// and reports it as "not recognized" -- which reads as a missing install.
const gradlew = `"${resolve(REPO_ROOT, isWindows ? "gradlew.bat" : "gradlew")}"`;

/**
 * Where Gradle writes one XML per test class, and the floor below which this
 * suite has not earned the word "parity".
 *
 * ParityFixtureCheck carries the three checks that replay every fixture; the
 * floor is those. RealRowsParityCheck is deliberately NOT counted on -- it
 * calls assumeTrue and skips unless FENCEFLOW_REAL_FIXTURE names a dump.
 */
const TEST_RESULTS = join(REPO_ROOT, "app", "build", "test-results", "testDebugUnitTest");
const PARITY_FLOOR = 3;

/**
 * How many parity tests actually EXECUTED since [since].
 *
 * Counted from the XML rather than inferred from the exit status, because a
 * suite can exit 0 having run nothing at all: a filter that matches no class,
 * or one that matches only a class which skips itself. An assumption failure
 * is recorded as skipped, so it is subtracted -- a skipped test compared no
 * prices.
 *
 * Only files written after the run started are counted, so a stale result
 * from an earlier run cannot vouch for this one.
 */
function parityTestsThatRan(since) {
  if (!existsSync(TEST_RESULTS)) return 0;
  let ran = 0;
  for (const name of readdirSync(TEST_RESULTS)) {
    if (!/^TEST-.*\.xml$/i.test(name)) continue;
    if (!/parity/i.test(name)) continue;
    const full = join(TEST_RESULTS, name);
    if (statSync(full).mtimeMs + 1000 < since) continue;
    const xml = readFileSync(full, "utf8");
    const total = /\btests="(\d+)"/.exec(xml);
    const skipped = /\bskipped="(\d+)"/.exec(xml);
    if (total) ran += Number(total[1]) - (skipped ? Number(skipped[1]) : 0);
  }
  return ran;
}

const kotlinStartedAt = Date.now();

// THE PATTERN IS PACKAGE-QUALIFIED ON PURPOSE -- DO NOT "SIMPLIFY" IT BACK TO
// "*Parity*". That form is expanded before Gradle sees it: the MSYS runtime
// globs arguments case-insensitively when the wrapper launches java.exe, even
// through quotes, so a file named ADMIN_PHONE_PARITY_2026-10-22.md in the repo
// root silently became the test filter and the whole gate failed with "no
// tests found". A dotted package name matches no filename.
// --rerun IS LOAD-BEARING -- DO NOT DROP IT TO SAVE 90 SECONDS. Gradle will
// otherwise report this task UP-TO-DATE and skip it, which breaks the gate in
// two ways: no result XML is written, so parityTestsThatRan() sees nothing;
// and, far worse, fixtures/pricing/*.json is not an input of any task (the
// tests open those files at runtime), so a CHANGED FIXTURE does not make the
// task out of date. Without --rerun the gate can call the engines identical
// from cache without having read a single fixture.
const kotlin = suite(
  "kotlin parity",
  `${gradlew} testDebugUnitTest --tests "com.fenceestimator.app.estimate.parity.*" --rerun --console=plain -q`,
  {
    JAVA_HOME: JDK_HOME,
    PATH: `${JDK_HOME}${isWindows ? "\\bin;" : "/bin:"}${process.env.PATH ?? ""}`,
  },
);

const npx = isWindows ? "npx.cmd" : "npx";

const typescript = suite(
  "typescript parity",
  `${npx} -y tsx supabase/functions/_shared/pricing/parity.ts`,
);

// The hand-computed money cases -- see the header. Added 24 Oct 2026, after
// smoke.ts was found sitting at 119 of 130 with nothing in the repo running it:
// no script, no npm task, no gate. Eleven expectations had gone stale behind
// the 2026.10.4/10.7/10.9 gate-post and brace/stiffener changes and nobody
// could have known, because the only thing that would have said so was a
// command a person had to remember to type.
//
// It earns its place here rather than being left to parity.ts because the two
// suites prove different things. parity.ts replays fixtures the Kotlin engine
// GENERATED, so it proves the engines agree; it cannot notice both of them
// being wrong together. smoke.ts holds figures a person worked out from the
// pricing rules with a pencil, so it is the only check in this gate that can
// disagree with both engines at once.
const smoke = suite(
  "pricing smoke",
  `${npx} -y tsx supabase/functions/_shared/pricing/smoke.ts`,
);

// What a commit writes -- see the header. Both run whatever the parity
// suites said, so one red run names every broken piece.
const commitPlan = suite("commit plan", `${npx} -y tsx supabase/functions/_shared/pricing/load_test.ts`);
const takeoffMerge = suite("takeoff merge", `${npx} -y tsx tests/price-job-takeoff-merge.test.mjs`);

// How many Kotlin parity tests really ran. Read once, used both for the
// failure message and for the did-it-prove-anything check below.
const kotlinRan = parityTestsThatRan(kotlinStartedAt);

if (!kotlin && kotlinRan === 0) {
  console.log(
    "\nThe Kotlin parity suite never ran: the build failed before executing a test, " +
      "so the engines have NOT disagreed -- nothing was compared.",
  );
  console.log(
    "      Look for a build error above, not a pricing difference. One known cause: a file " +
      "whose name matches the --tests pattern.",
  );
  process.exit(1);
}
if (!(kotlin && typescript)) {
  console.log("\nParity is red. Nothing ships until both engines agree on the same fixtures.");
  process.exit(1);
}
// A suite that exits 0 having compared nothing is not green. This is the
// check that would have caught the filter breaking quietly instead of loudly.
if (kotlinRan < PARITY_FLOOR) {
  console.log(
    `\nThe Kotlin parity suite passed but only ${kotlinRan} test(s) ran, fewer than the ${PARITY_FLOOR} that replay the fixtures.`,
  );
  console.log("      A suite that compared nothing cannot say the engines agree. Check the --tests filter.");
  process.exit(1);
}
// Gated in the order the suites RAN, so the message a red run ends on names
// the first thing that broke rather than whichever check happens to be last.
if (!smoke) {
  console.log(
    "\nThe hand-computed money cases are red. The engines may still agree with each other -- " +
      "this suite is the one that says whether they agree with the PRICING RULES.",
  );
  console.log(
    "      Decide which is wrong before touching either engine. If the expectation is stale, fix it and " +
      "write beside it which change made it stale. If the engine is wrong, the fix lands in BOTH engines " +
      "in one commit, with the version bumped and the fixtures regenerated -- never one side alone.",
  );
  process.exit(1);
}
if (!(commitPlan && takeoffMerge)) {
  console.log("\nThe commit plan is red. Nothing ships until a re-price leaves the lines somebody edited alone.");
  process.exit(1);
}
console.log(
  `\nParity is green: both engines reproduce the fixtures exactly (${kotlinRan} Kotlin parity tests ran), ` +
    `the hand-computed money cases still come out to the cent, and a commit leaves edited lines alone.`,
);
